  'resize_image': {
    description: "Resize image tool. Resizes images to specified target dimensions.\r\n\r\n**Features**:\r\n- Resize image to specified width and height\r\n- Uses stretch fill mode (does not preserve aspect ratio)\r\n- Suitable for scenarios requiring exact dimensions\r\n\r\n**Parameters**:\r\n- width: Target width (pixels, required)\r\n- height: Target height (pixels, required)\r\n- image_path: Source image path (required)\r\n- output_path: Output file path (required)\r\n\r\n**Examples**:\r\n- Resize to 800x600: width=800, height=600\r\n- Resize to square 512x512: width=512, height=512\r\n- Resize to 1920x1080: width=1920, height=1080\r\n\r\n**Supported Formats**: PNG, JPEG, WebP (auto-selected based on output path extension)\r\n\r\n**Limits**:\r\n- Maximum 10 resize tasks per call\r\n- Target dimensions cannot exceed 16384x16384",
    parameters: {
      "images": {"type":"array","description":"Batch mode: Resize task array. Each task can independently configure input, output, and target dimensions. MUST be an array even for single task.","items":{"type":"object"}},
      "image_path": {"type":"string"},
      "output_path": {"type":"string"},
      "width": {"type":"integer","description":"Single mode: Target width (pixels, required)"},
      "height": {"type":"integer","description":"Single mode: Target height (pixels, required)"},
    },
    parametersDynamic: true,
    source: "backend/tools/media/resize_image.ts",
  },
  'rotate_image': {
    description: "Rotate image tool. Rotates images clockwise to specified angle.\r\n\r\n**Features**:\r\n- Supports any rotation angle (positive, negative, over 360 degrees)\r\n- Positive angles rotate clockwise\r\n- Negative angles rotate counter-clockwise\r\n- Automatically calculates minimum bounding rectangle canvas\r\n\r\n**Background Fill**:\r\n- PNG/WebP: Transparent background\r\n- JPEG: Black background\r\n\r\n**Parameters**:\r\n- angle: Rotation angle (required, positive for clockwise)\r\n- image_path: Source image path (required)\r\n- output_path: Output file path (required)\r\n- format: Output format (optional: png, jpg, webp. If not specified, uses original format or infers from output path)\r\n\r\n**Examples**:\r\n- Rotate 90° clockwise: angle=90\r\n- Rotate 45° counter-clockwise: angle=-45\r\n- Rotate 180° (flip): angle=180\r\n\r\n**Supported Formats**: PNG, JPEG, WebP (selected based on format parameter or output path extension)\r\n\r\n**Limits**:\r\n- Maximum 10 rotate tasks per call",
    parameters: {
      "images": {"type":"array","description":"Batch mode: Rotate task array. Each task can independently configure input, output, angle, and format. MUST be an array even for single task.","items":{"type":"object"}},
      "image_path": {"type":"string"},
      "output_path": {"type":"string"},
      "angle": {"type":"number","description":"Single mode: Rotation angle (required, positive for clockwise, any value)"},
      "format": {"type":"string","description":"Single mode: Output format (optional: png, jpg, webp)"},
    },
    parametersDynamic: true,
    source: "backend/tools/media/rotate_image.ts",
  },
  'search_in_files': {
    descriptionDynamic: true,
    parameters: {
      "mode": {"type":"string","description":"Operation mode. Use \"search\" for finding content only, use \"replace\" for search and replace.","enum":["search","replace"],"default":"search"},
      "query": {"type":"string","description":"Search keyword, exact phrase, space-separated keywords, or regular expression. If query contains regex syntax such as \"|\", \".*\", \".+\", \"\\.\", \"\\d\", \"[]\", \"()\", \"^\", or \"$\", set isRegex=true. Search mode first tries the full literal phrase and may retry space-separated keywords when isRegex=false.","required":true},
      "path": {"type":"string","description":"Search path relative to workspace root. Use \"dir/\" (trailing slash) for directories, or \"dir/file.ext\" for a single file. Default \".\" searches the entire workspace.","default":"."},
      "pattern": {"type":"string","description":"File matching pattern, e.g., \"*.ts\" or \"**/*.js\"","default":"**/*"},
      "isRegex": {"type":"boolean","description":"Whether to treat query as a regular expression. Default: false. When false, regex-looking characters are searched literally; zero-result searches may return suspected_regex diagnostics instead of silently changing semantics.","default":false},
      "caseSensitive": {"type":"boolean","description":"Whether matching is case-sensitive. Defaults differ by mode: search mode defaults to false (case-insensitive), replace mode defaults to true (conservative exact replacement). Pass explicitly to override, e.g. set caseSensitive=false in replace mode to replace matches found by a case-insensitive search."},
      "maxResults": {"type":"number","description":"[Search mode] Maximum number of match results","default":100},
      "replace": {"type":"string","description":"[Replace mode] Replacement string. REQUIRED when mode is \"replace\"; omitting it would silently replace all matches with empty string. Supports regex capture groups like $1, $2 when isRegex is true."},
      "maxFiles": {"type":"number","description":"[Replace mode] Maximum number of files to process","default":50},
    },
    source: "backend/tools/search/declaration.ts",
  },
